function validate([answers]) {
  if (answers.length < 1 || answers.length > 1000) return 'answers needs 1 to 1000 values.';
  if (answers.some(v => !Number.isInteger(v) || v < 0 || v > 999)) return 'Each answer is an integer from 0 to 999.';
  return null;
}

