function numRabbits(answers) {
  // Seat rabbits one by one: join an unfinished color group with the same reply, or open a new one.
  const freeSeats = [];
  let total = 0;
  for (const reply of answers) {
    const group = freeSeats.findIndex(g => g.reply === reply && g.left > 0);
    if (group >= 0) {
      freeSeats[group].left--;
    } else {
      total += reply + 1;
      freeSeats.push({ reply, left: reply });
    }
  }
  return total;
}

