function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 1 + Math.floor(rand() * 9);
  const mode = rand();
  const top = large ? (mode < 0.3 ? 999 : mode < 0.7 ? 40 : 3) : (mode < 0.15 ? 999 : 4);
  if (large && mode > 0.9) {
    const value = Math.floor(rand() * 1000);
    return [Array.from({ length: n }, () => value)];
  }
  return [Array.from({ length: n }, () => Math.floor(rand() * (top + 1)))];
}
